<template><main class="zj-workspace"><header class="zj-heading"><div><div class="zj-eyebrow">众基消防 / 人员管理</div><h1>公司员工</h1><p>员工档案独立于登录账号，未注册系统的员工也可登记、关联资料并参与项目及报账。</p></div><el-button v-hasPermi="['management:employee:edit']" type="primary" @click="edit()">添加员工</el-button></header><section class="zj-card"><div class="zj-filters"><el-input v-model="query.name" placeholder="搜索姓名或类型" clearable @keyup.enter="search"/><el-select v-model="query.active" clearable placeholder="全部状态"><el-option label="在用" value="1"/><el-option label="已停用 / 离职" value="0"/></el-select><el-button type="primary" @click="search">查询</el-button></div><el-alert v-if="error" title="人员加载失败，请重试" type="error" :closable="false"/><el-table v-loading="loading" :data="rows"><el-table-column prop="id" label="档案ID" width="100"/><el-table-column prop="name" label="姓名" min-width="160"/><el-table-column prop="employeeType" label="类型" min-width="180"/><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="row.active?'success':'info'">{{row.active?'在用':'已停用'}}</el-tag></template></el-table-column><el-table-column prop="remark" label="备注 / 待核对信息" min-width="250"/><el-table-column label="操作" width="150"><template #default="{row}"><el-button v-hasPermi="['management:employee:edit']" link @click="edit(row)">编辑</el-button><el-button v-hasPermi="['management:credential:list']" link type="primary" @click="$router.push({path:'/zhongji/report-credentials',query:{employeeId:row.id}})">资料</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.pageNum" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load"/></section><el-drawer v-model="open" title="员工档案" size="min(560px,96vw)" :before-close="close"><el-form ref="formRef" :model="form" label-position="top" :disabled="saving"><el-form-item label="姓名" prop="name" :rules="[{required:true,message:'请填写姓名'}]"><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="类型" prop="employeeType" :rules="[{required:true,message:'请选择或输入类型'}]"><el-select v-model="form.employeeType" allow-create filterable style="width:100%" placeholder="可手动输入类型"><el-option v-for="t in ['工程师','操作员','业务人员','行政人员','其他','待确认']" :key="t" :value="t" :label="t"/></el-select></el-form-item><el-form-item label="是否在用"><el-switch v-model="form.active"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" :rows="5" maxlength="2000"/></el-form-item><el-alert title="停用后不再出现在新的业务选择中，原项目、报账及资料关联继续保留。" type="info" :closable="false"/></el-form><template #footer><el-button @click="close(()=>open=false)">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-drawer></main></template>
<script setup>
import request from '@/utils/request';import {ElMessage,ElMessageBox} from 'element-plus';import '@/assets/styles/zhongji.scss';import {onBeforeRouteLeave} from 'vue-router'
const rows=ref([]),total=ref(0),query=reactive({name:'',active:'',pageNum:1,pageSize:20}),loading=ref(false),error=ref(false),open=ref(false),saving=ref(false),formRef=ref(),form=ref({});let sequence=0,snapshot=''
async function load(){const n=++sequence;loading.value=true;error.value=false;try{const r=await request({url:'/management/employees',params:query});if(n===sequence){rows.value=r.rows;total.value=r.total}}catch{if(n===sequence)error.value=true}finally{if(n===sequence)loading.value=false}}
function search(){query.pageNum=1;load()}function edit(row){form.value=row?{...row,active:!!row.active}:{name:'',employeeType:'',active:true,remark:''};snapshot=JSON.stringify(form.value);open.value=true;nextTick(()=>formRef.value?.clearValidate())}
async function leave(){if(saving.value)return false;if(open.value&&snapshot!==JSON.stringify(form.value)){try{await ElMessageBox.confirm('放弃未保存的员工档案？')}catch{return false}}return true}async function close(done){if(await leave())done()}onBeforeRouteLeave(leave)
async function save(){if(saving.value||!await formRef.value.validate().catch(()=>false))return;saving.value=true;try{await request({url:'/management/employees',method:'post',data:form.value});open.value=false;ElMessage.success('员工档案已保存');await load()}finally{saving.value=false}}onMounted(load)
</script>
